#mysteries{位置:相対;オーバーフロー:非表示}
    #ミステリー .wrap{位置:相対;z-インデックス:3}
    .myst-filterbar{display:flex;flex-wrap:wrap;gap:20px 28px;align-items:flex-end;margin-bottom:14px}
    .myst-filter-group{display:flex;flex-direction:column;gap:9px;min-width:0}
    .myst-filter-label{font-family:"Space Mono",ui-monospace,monospace;font-size:10px;letter-spacing:.24em;text-transform:uppercase;color:#d3a8c2}
    .myst-chip-row{ディスプレイ:フレックス;フレックスラップ:ラップ;ギャップ:8px}
    .myst-チップ{
      ディスプレイ:インラインフレックス;整列項目:センター;ギャップ:8px;カーソル:ポインター;
      パディング:9px 15px;ボーダー半径:999px;
      font-family:"Space Mono",ui-monospace,monospace;font-size:11px;
      文字間隔:.14em;テキスト変換:大文字;色:#f4e3d7;
      背景:rgba(20,7,44,.72);ボーダー:1px ソリッド rgba(255,45,124,.3);
      トランジション:変換 .15 秒のイーズ、ボックスシャドウ .2 秒のイーズ、ボーダーカラー .2 秒のイーズ;
    }
    .myst-chip:hover{transform:translateY(-1px);border-color:rgba(255,45,124,.65);box-shadow:0 0 20px rgba(255,45,124,.25)}
    .myst-chip.active{
      背景:var(--vi-grad-sunset,linear-gradient(90deg,#ff2d7c,#ff8a3d 52%,#ffd166));
      color:var(--vi-ink,#33051c);border-color:transparent;font-weight:700;
      box-shadow:0 8px 22px -8px rgba(255,45,124,.65);
    }
    .myst-chip .myst-dot{幅:8px;高さ:8px;ボーダー半径:99px;flex:0 0 auto}
    .myst-chip.active .myst-dot{outline:1px ソリッド rgba(51,5,28,.4)}
    .myst-dot--resolved{background:linear-gradient(135deg,var(--vi-gold,#ffd166),#7ee08c)}
    .myst-dot--open{background:var(--vi-pink,#ff2d7c);box-shadow:0 0 10px rgba(255,45,124,.8)}
    .myst-dot--lenda{背景:var(--vi-purple,#7b2ff7);box-shadow:0 0 10px rgba(123,47,247,.8)}
    .myst-dot--all{background:#f4e3d7}
    .myst-チップ小{
      フォントサイズ:10px;パディング:2px 7px;ボーダー半径:99px;文字間隔:.08em;
      背景:rgba(11,13,42,.55);カラー:継承;ボーダー:1px ソリッド rgba(255,255,255,.18);
    }
    .myst-chip.active small{背景:rgba(51,5,28,.22);ボーダーカラー:rgba(51,5,28,.3)}
    .myst-select{
      外観: なし;-webkit の外観: なし;カーソル: ポインター;最小幅: 220px;
      パディング:10px 38px 10px 14px;ボーダー半径:10px;
      font-family:"Space Mono",ui-monospace,monospace;font-size:12px;letter-spacing:.06em;
      カラー:#fff5ec;背景:rgba(20,7,44,.72);ボーダー:1px ソリッド rgba(255,45,124,.3);
      背景-画像:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='12' height='8' viewBox='0 0 12 8'><path d='M1 1l5 5 5-5' fill='none' ストローク='%23ff2d7c' ストローク-幅='2'ストローク-linecap='round'/></svg>");
      背景繰り返し:繰り返しなし;背景位置:右 14 ピクセル中央;
    }
    .myst-select:focus{outline:none;border-color:rgba(255,45,124,.7);box-shadow:0 0 18px rgba(255,45,124,.3)}
    .myst-select オプション{背景:#0b0d2a;色:#fff5ec}
    .myst-status-desc{
      マージン:0 0 18px;最大幅:760px;カラー:#d9c3d2;フォントサイズ:14px;行の高さ:1.6;
      border-left:3px ソリッド rgba(255,45,124,.55);padding-left:14px;
    }
    .myst-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(330px,1fr));gap:18px;align-items:start}
    .myst-card{ディスプレイ:フレックス;フレックス方向:列;ギャップ:0;パディング:22px 22px 18px}
    .myst-card-top{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-bottom:14px}
    .myst-file-no{font-family:"Space Mono",ui-monospace,monospace;font-size:10px;letter-spacing:.22em;color:#b98ca9;text-transform:uppercase}
    .myst-stamp{transform:rotate(-2deg);font-size:10px;letter-spacing:.2em;padding:6px 13px}
    .myst-stamp--解決済み{
      背景:linear-gradient(90deg,var(--vi-gold,#ffd166),#7ee08c);
      color:var(--vi-ink,#33051c);box-shadow:0 8px 22px -8px rgba(255,209,102,.7),0 0 20px rgba(126,224,140,​​.25);
    }
    .myst-stamp--open{color:var(--vi-pink,#ff2d7c);box-shadow:0 0 22px rgba(255,45,124,.4)}
    .myst-stamp--legend{
      color:#cfa9ff;box-shadow:0 0 22px rgba(123,47,247,.45);
      背景:
        線形勾配(rgba(26,9,54,.9),rgba(26,9,54,.9)) パディングボックス,
        線形グラデーション(90度、var(--vi-purple、#7b2ff7)、var(--vi-pink-2、#f152ff)) ボーダーボックス;
    }
    .myst-ゲームチップ{
      表示:インラインフレックス;整列アイテム:センター;ギャップ:6ピクセル;マージンボトム:10ピクセル;
      font-family:"Space Mono",ui-monospace,monospace;font-size:10px;
      文字間隔:.18em;テキスト変換:大文字;色:var(--vi-gold,#ffd166);
    }
    .myst-game-chip::before{content:"";width:14px;height:1px;background:var(--vi-gold,#ffd166);opacity:.7}
    .myst-card h3{マージン:0 0 10px;フォントサイズ:20px;行の高さ:1.25;カラー:#fff5ec}
    .myst-desc{マージン:0;カラー:#d9c8d4;フォントサイズ:14px;行の高さ:1.62}
    .myst-toggle{margin-top:16px;align-self:flex-start}
    .myst-body{margin-top:16px;padding-top:16px;border-top:1px 破線 rgba(255,45,124,.35)}
    .myst-evidence-label{
      ディスプレイ:フレックス;整列項目:センター;ギャップ:8px;マージン:16px 0 4px;
      font-family:"Space Mono",ui-monospace,monospace;font-size:10px;
      文字間隔:.26em;テキスト変換:大文字;色:#ff9ec4;
    }
    .myst-evidence-label:first-child{margin-top:0}
    .myst-evidence-label::after{content:"";flex:1;height:1px;background:rgba(255,45,124,.25)}
    .myst-list{リストスタイル:なし;マージン:8px 0 0;パディング:0}
    .myst-list li{display:flex;gap:10px;align-items:baseline;margin-bottom:8px;color:#e6d6dd;font-size:13.5px;line-height:1.6}
    .myst-idx{
      flex:0 0 auto;font-family:"Space Mono",ui-monospace,monospace;font-size:10px;
      文字間隔:.08em;色:var(--vi-gold,#ffd166);不透明度:.85;最小幅:30px;
    }
    .myst-resolution{
      マージントップ:18px;パディング:14px 16px;ボーダー半径:10px;
      ボーダー:1px 破線 rgba(255,209,102,.6);背景:rgba(255,209,102,.07);
    }
    .myst-resolution .myst-evidence-label{color:var(--vi-gold,#ffd166);margin-top:0}
    .myst-resolution .myst-evidence-label::after{background:rgba(255,209,102,.35)}
    .myst-resolution p{margin:8px 0 0;color:#ffe9bd;font-size:13.5px;line-height:1.62}
    .myst-どこ{
      ディスプレイ:フレックス;ギャップ:10ピクセル;整列アイテム:ベースライン;マージントップ:16ピクセル;
      font-family:"Space Mono",ui-monospace,monospace;font-size:12px;
      カラー:#cdb4c6;行の高さ:1.55;
    }
    .myst-where svg{flex:0 0 auto;width:14px;height:14px;transform:translateY(2px);color:var(--vi-pink,#ff2d7c)}
    .myst-empty{
      パディング:34ピクセル 26ピクセル;テキスト整列:センター;カラー:#d3a8c2;
      font-family:"Space Mono",ui-monospace,monospace;font-size:13px;letter-spacing:.08em;
    }
    @media (最大幅:760px){
      .myst-filterbar{flex-direction:column;align-items:stretch}
      .myst-select{幅:100%}
      .myst-grid{グリッドテンプレート列:1fr}
      .myst-card{パディング:18px 16px 16px}
    }
    @media (prefers-reduced-motion:reduce){
      .myst-chip,.myst-chip:hover{変換:なし;遷移:なし}
    }
